                match c {
                    'U' => opts.protocols.push(Protocol::Udp),
                    'T' => opts.protocols.push(Protocol::Tcp),
                    'S' => opts.protocols.push(Protocol::Tls),
                    'H' => opts.protocols.push(Protocol::Https),
                    '1' => opts.format = OutputFormat::Short,
                    'J' => {
                        if opts.format != OutputFormat::Short {
                            opts.format = OutputFormat::Json;
                        }
                    }
                    'v' => want_version = true,
                    '?' => want_help = true,
                    'q' | 't' | 'n' | 'Z' => {
                        let mut rest = String::from_utf8_lossy(&bytes[j + 1..]).into_owned();
