                                    "Argument to option '{}' missing",
                                    c
                                ));
                            }
                            argv[i].clone()
                        };
                        match c {
                            'q' => opts.queries.push(value),
                            't' => match types::parse_type(&value) {
                                Some(t) => opts.types.push(t),
                                None => {
                                    return ParseResult::Error(format!(
                                        "Invalid query type {:?}",
                                        value
                                    ))
                                }
                            },
                            'n' => opts.nameservers.push(value),
                            'Z' => {
                                if let Err(e) = parse_tweak(&value, &mut opts.tweaks) {
                                    return ParseResult::Error(e);
                                }
                            }
                            _ => unreachable!(),
