    pub flags: u16,
    pub queries: Vec<Query>,
    pub answers: Vec<Record>,
    pub authorities: Vec<Record>,
    pub additionals: Vec<Record>,
}

impl Response {
    pub fn rcode(&self) -> u8 {
        (self.flags & 0x000F) as u8
    }
    pub fn truncated(&self) -> bool {
        (self.flags & 0x0200) != 0
    }
}

