// DNS wire-format encoding and decoding.

use std::net::{Ipv4Addr, Ipv6Addr};

use crate::args::{EdnsSetting, Tweaks};
use crate::dns::{Query, RData, Record, Response};

pub struct Encoder {
    buf: Vec<u8>,
}

impl Encoder {
    pub fn new() -> Self {
        Self { buf: Vec::new() }
    }

    pub fn into_bytes(self) -> Vec<u8> {
        self.buf
    }

    fn push_u8(&mut self, v: u8) {
        self.buf.push(v);
    }
    fn push_u16(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_be_bytes());
    }
    fn push_u32(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_be_bytes());
    }

    fn write_name(&mut self, name: &str) {
        // Encode each label as <len><bytes>. Trailing '.' or empty = root.
        let trimmed = name.trim_end_matches('.');
        if !trimmed.is_empty() {
            for label in trimmed.split('.') {
                let bytes = label.as_bytes();
                if bytes.is_empty() {
                    continue;
                }
                // Limit to 63 octets per label.
                let len = std::cmp::min(bytes.len(), 63);
                self.push_u8(len as u8);
                self.buf.extend_from_slice(&bytes[..len]);
            }
        }
        self.push_u8(0);
    }
}

pub fn build_query(
    txid: u16,
    queries: &[Query],
    edns: EdnsSetting,
    tweaks: &Tweaks,
) -> Vec<u8> {
    let mut e = Encoder::new();
    e.push_u16(txid);
    // Flags: QR=0, OPCODE=0, AA, TC=0, RD=1, RA=0, Z=0, AD, CD, RCODE=0.
    let mut flags: u16 = 0x0100; // RD=1
    if tweaks.aa {
        flags |= 0x0400;
    }
    if tweaks.ad {
        flags |= 0x0020;
    }
    if tweaks.cd {
        flags |= 0x0010;
    }
    e.push_u16(flags);
    e.push_u16(queries.len() as u16);
    e.push_u16(0); // ANCOUNT
    e.push_u16(0); // NSCOUNT
    let include_opt = edns != EdnsSetting::Disable;
    e.push_u16(if include_opt { 1 } else { 0 }); // ARCOUNT

    for q in queries {
        e.write_name(&q.name);
        e.push_u16(q.qtype);
        e.push_u16(q.qclass);
    }
    if include_opt {
        // OPT pseudo-record.
        e.push_u8(0); // empty name
        e.push_u16(41); // OPT
        e.push_u16(tweaks.bufsize); // UDP payload size
        e.push_u32(0); // ext rcode + version + flags
        e.push_u16(0); // rdata length
    }
    e.into_bytes()
}

// ---------- Decoder ----------

pub struct Decoder<'a> {
    buf: &'a [u8],
    pos: usize,
}

impl<'a> Decoder<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        Self { buf, pos: 0 }
    }

    fn read_u8(&mut self) -> Result<u8, String> {
        if self.pos >= self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = self.buf[self.pos];
        self.pos += 1;
        Ok(v)
    }
    fn read_u16(&mut self) -> Result<u16, String> {
        if self.pos + 2 > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = u16::from_be_bytes([self.buf[self.pos], self.buf[self.pos + 1]]);
        self.pos += 2;
        Ok(v)
    }
    fn read_u32(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = u32::from_be_bytes([
            self.buf[self.pos],
            self.buf[self.pos + 1],
            self.buf[self.pos + 2],
            self.buf[self.pos + 3],
        ]);
        self.pos += 4;
        Ok(v)
    }
    fn read_bytes(&mut self, n: usize) -> Result<Vec<u8>, String> {
        if self.pos + n > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let out = self.buf[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(out)
    }

    /// Read a domain name with compression-pointer support. Returns the fully
    /// decoded name (with trailing '.'), and advances `self.pos` past the
    /// *in-place* name only (compression pointers do not move the main
    /// cursor beyond where they appear).
    fn read_name(&mut self) -> Result<String, String> {
        let mut out = String::new();
        let mut pos = self.pos;
        let mut jumped = false;
        let mut final_pos = self.pos;
        let mut hops = 0;
        loop {
            if pos >= self.buf.len() {
                return Err("unexpected end of packet (in name)".into());
            }
            let len = self.buf[pos];
            if len == 0 {
                pos += 1;
                if !jumped {
                    final_pos = pos;
                }
                break;
            }
            if (len & 0xC0) == 0xC0 {
                if pos + 1 >= self.buf.len() {
                    return Err("truncated compression pointer".into());
                }
                let lo = self.buf[pos + 1];
                let new_pos = (((len & 0x3F) as usize) << 8) | (lo as usize);
                if !jumped {
                    final_pos = pos + 2;
                }
                jumped = true;
                pos = new_pos;
                hops += 1;
                if hops > 20 {
                    return Err("too many compression pointers".into());
                }
                continue;
            }
            if (len & 0xC0) != 0 {
                return Err("invalid label length".into());
            }
            let len = len as usize;
            if pos + 1 + len > self.buf.len() {
                return Err("label extends past end of packet".into());
            }
            if !out.is_empty() {
                out.push('.');
            }
            let lbl = &self.buf[pos + 1..pos + 1 + len];
            for &b in lbl {
                // Escape non-printable bytes with \DDD following RFC 1035.
                if b < 0x21 || b > 0x7E || b == b'.' || b == b'\\' || b == b'"' {
                    if b == b'.' || b == b'\\' || b == b'"' {
                        out.push('\\');
                        out.push(b as char);
                    } else {
