        rtype,
        rclass,
        ttl,
        data,
    })
}

fn parse_rdata(
    rtype: u16,
    d: &mut Decoder,
    start: usize,
    rdlen: usize,
    _rdata_bytes: &[u8],
) -> Result<RData, String> {
