    /// decoded name (with trailing '.'), and advances `self.pos` past the
    /// *in-place* name only (compression pointers do not move the main
    /// cursor beyond where they appear).
    fn read_name(&mut self) -> Result<String, String> {
        let mut out = String::new();
        let mut pos = self.pos;
        let mut jumped = false;
        let mut final_pos = self.pos;
        let mut hops = 0;
        loop {
            if pos >= self.buf.len() {
                return Err("unexpected end of packet (in name)".into());
            }
            let len = self.buf[pos];
            if len == 0 {
                pos += 1;
                if !jumped {
                    final_pos = pos;
                }
                break;
            }
            if (len & 0xC0) == 0xC0 {
                if pos + 1 >= self.buf.len() {
                    return Err("truncated compression pointer".into());
                }
                let lo = self.buf[pos + 1];
                let new_pos = (((len & 0x3F) as usize) << 8) | (lo as usize);
                if !jumped {
                    final_pos = pos + 2;
                }
                jumped = true;
                pos = new_pos;
                hops += 1;
                if hops > 20 {
                    return Err("too many compression pointers".into());
                }
                continue;
            }
            if (len & 0xC0) != 0 {
                return Err("invalid label length".into());
            }
            let len = len as usize;
            if pos + 1 + len > self.buf.len() {
                return Err("label extends past end of packet".into());
            }
            if !out.is_empty() {
                out.push('.');
            }
            let lbl = &self.buf[pos + 1..pos + 1 + len];
            for &b in lbl {
                // Escape non-printable bytes with \DDD following RFC 1035.
                if b < 0x21 || b > 0x7E || b == b'.' || b == b'\\' || b == b'"' {
