// DNS wire-format encoding and decoding.

use std::net::{Ipv4Addr, Ipv6Addr};

use crate::args::{EdnsSetting, Tweaks};
use crate::dns::{Query, RData, Record, Response};

pub struct Encoder {
    buf: Vec<u8>,
}

impl Encoder {
    pub fn new() -> Self {
        Self { buf: Vec::new() }
    }

    pub fn into_bytes(self) -> Vec<u8> {
        self.buf
    }

    fn push_u8(&mut self, v: u8) {
        self.buf.push(v);
    }
    fn push_u16(&mut self, v: u16) {
        self.buf.extend_from_slice(&v.to_be_bytes());
    }
    fn push_u32(&mut self, v: u32) {
        self.buf.extend_from_slice(&v.to_be_bytes());
    }

    fn write_name(&mut self, name: &str) {
        // Encode each label as <len><bytes>. Trailing '.' or empty = root.
        let trimmed = name.trim_end_matches('.');
        if !trimmed.is_empty() {
            for label in trimmed.split('.') {
                let bytes = label.as_bytes();
                if bytes.is_empty() {
                    continue;
                }
                // Limit to 63 octets per label.
                let len = std::cmp::min(bytes.len(), 63);
                self.push_u8(len as u8);
                self.buf.extend_from_slice(&bytes[..len]);
            }
        }
        self.push_u8(0);
    }
}

pub fn build_query(
    txid: u16,
    queries: &[Query],
    edns: EdnsSetting,
    tweaks: &Tweaks,
) -> Vec<u8> {
    let mut e = Encoder::new();
    e.push_u16(txid);
    // Flags: QR=0, OPCODE=0, AA, TC=0, RD=1, RA=0, Z=0, AD, CD, RCODE=0.
    let mut flags: u16 = 0x0100; // RD=1
    if tweaks.aa {
        flags |= 0x0400;
    }
    if tweaks.ad {
        flags |= 0x0020;
    }
    if tweaks.cd {
        flags |= 0x0010;
    }
    e.push_u16(flags);
    e.push_u16(queries.len() as u16);
    e.push_u16(0); // ANCOUNT
    e.push_u16(0); // NSCOUNT
    let include_opt = edns != EdnsSetting::Disable;
    e.push_u16(if include_opt { 1 } else { 0 }); // ARCOUNT

    for q in queries {
        e.write_name(&q.name);
        e.push_u16(q.qtype);
        e.push_u16(q.qclass);
    }
    if include_opt {
        // OPT pseudo-record.
        e.push_u8(0); // empty name
        e.push_u16(41); // OPT
        e.push_u16(tweaks.bufsize); // UDP payload size
        e.push_u32(0); // ext rcode + version + flags
        e.push_u16(0); // rdata length
    }
    e.into_bytes()
}

// ---------- Decoder ----------

pub struct Decoder<'a> {
    buf: &'a [u8],
    pos: usize,
}

impl<'a> Decoder<'a> {
    pub fn new(buf: &'a [u8]) -> Self {
        Self { buf, pos: 0 }
    }

    fn read_u8(&mut self) -> Result<u8, String> {
        if self.pos >= self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = self.buf[self.pos];
        self.pos += 1;
        Ok(v)
    }
    fn read_u16(&mut self) -> Result<u16, String> {
        if self.pos + 2 > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = u16::from_be_bytes([self.buf[self.pos], self.buf[self.pos + 1]]);
        self.pos += 2;
        Ok(v)
    }
    fn read_u32(&mut self) -> Result<u32, String> {
        if self.pos + 4 > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let v = u32::from_be_bytes([
            self.buf[self.pos],
            self.buf[self.pos + 1],
            self.buf[self.pos + 2],
            self.buf[self.pos + 3],
        ]);
        self.pos += 4;
        Ok(v)
    }
    fn read_bytes(&mut self, n: usize) -> Result<Vec<u8>, String> {
        if self.pos + n > self.buf.len() {
            return Err("unexpected end of packet".into());
        }
        let out = self.buf[self.pos..self.pos + n].to_vec();
        self.pos += n;
        Ok(out)
    }

    /// Read a domain name with compression-pointer support. Returns the fully
    /// decoded name (with trailing '.'), and advances `self.pos` past the
    /// *in-place* name only (compression pointers do not move the main
    /// cursor beyond where they appear).
    fn read_name(&mut self) -> Result<String, String> {
        let mut out = String::new();
        let mut pos = self.pos;
        let mut jumped = false;
        let mut final_pos = self.pos;
        let mut hops = 0;
        loop {
            if pos >= self.buf.len() {
                return Err("unexpected end of packet (in name)".into());
            }
            let len = self.buf[pos];
            if len == 0 {
                pos += 1;
                if !jumped {
                    final_pos = pos;
                }
                break;
            }
            if (len & 0xC0) == 0xC0 {
                if pos + 1 >= self.buf.len() {
                    return Err("truncated compression pointer".into());
                }
                let lo = self.buf[pos + 1];
                let new_pos = (((len & 0x3F) as usize) << 8) | (lo as usize);
                if !jumped {
                    final_pos = pos + 2;
                }
                jumped = true;
                pos = new_pos;
                hops += 1;
                if hops > 20 {
                    return Err("too many compression pointers".into());
                }
                continue;
            }
            if (len & 0xC0) != 0 {
                return Err("invalid label length".into());
            }
            let len = len as usize;
            if pos + 1 + len > self.buf.len() {
                return Err("label extends past end of packet".into());
            }
            if !out.is_empty() {
                out.push('.');
            }
            let lbl = &self.buf[pos + 1..pos + 1 + len];
            for &b in lbl {
                // Escape non-printable bytes with \DDD following RFC 1035.
                if b < 0x21 || b > 0x7E || b == b'.' || b == b'\\' || b == b'"' {
                    if b == b'.' || b == b'\\' || b == b'"' {
                        out.push('\\');
                        out.push(b as char);
                    } else {
                        out.push_str(&format!("\\{:03}", b));
                    }
                } else {
                    out.push(b as char);
                }
            }
            pos += 1 + len;
        }
        if !jumped {
            self.pos = final_pos;
        } else {
            self.pos = final_pos;
        }
        // Always add trailing dot.
        out.push('.');
        Ok(out)
    }
}

pub fn decode(buf: &[u8]) -> Result<Response, String> {
    let mut d = Decoder::new(buf);
    let txid = d.read_u16()?;
    let flags = d.read_u16()?;
    let qdcount = d.read_u16()?;
    let ancount = d.read_u16()?;
    let nscount = d.read_u16()?;
    let arcount = d.read_u16()?;

    let mut queries = Vec::with_capacity(qdcount as usize);
    for _ in 0..qdcount {
        let name = d.read_name()?;
        let qtype = d.read_u16()?;
        let qclass = d.read_u16()?;
        queries.push(Query { name, qtype, qclass });
    }

    let mut answers = Vec::with_capacity(ancount as usize);
    for _ in 0..ancount {
        answers.push(read_record(&mut d)?);
    }
    let mut authorities = Vec::with_capacity(nscount as usize);
    for _ in 0..nscount {
        authorities.push(read_record(&mut d)?);
    }
    let mut additionals = Vec::with_capacity(arcount as usize);
    for _ in 0..arcount {
        additionals.push(read_record(&mut d)?);
    }
    Ok(Response {
        txid,
        flags,
        queries,
        answers,
        authorities,
        additionals,
    })
}

fn read_record(d: &mut Decoder) -> Result<Record, String> {
    let name = d.read_name()?;
    let rtype = d.read_u16()?;
    let rclass = d.read_u16()?;
    let ttl = d.read_u32()?;
    let rdlen = d.read_u16()? as usize;
    let start = d.pos;
    if start + rdlen > d.buf.len() {
        return Err("rdata extends past end of packet".into());
    }
    // Build a sub-decoder for the rdata.
    let rdata_bytes = &d.buf[start..start + rdlen];
    let data = parse_rdata(rtype, d, start, rdlen, rdata_bytes)?;
    d.pos = start + rdlen;

    // Special-case: OPT record has overloaded class/ttl fields.
    if rtype == 41 {
        if let RData::Opt {
            udp_payload_size,
            ext_rcode,
            edns_version,
            flags,
            data: opt_data,
        } = &data
        {
            let _ = (udp_payload_size, ext_rcode, edns_version, flags, opt_data);
        }
        let name = "".to_string();
        let data = RData::Opt {
            udp_payload_size: rclass,
            ext_rcode: ((ttl >> 24) & 0xff) as u8,
            edns_version: ((ttl >> 16) & 0xff) as u8,
            flags: (ttl & 0xffff) as u16,
            data: rdata_bytes.to_vec(),
        };
        return Ok(Record {
            name,
            rtype,
            rclass,
            ttl,
            data,
        });
    }

    Ok(Record {
        name,
        rtype,
        rclass,
        ttl,
        data,
    })
}

fn parse_rdata(
    rtype: u16,
    d: &mut Decoder,
    start: usize,
    rdlen: usize,
    _rdata_bytes: &[u8],
) -> Result<RData, String> {
    let saved = d.pos;
    d.pos = start;
    let rd = match rtype {
        1 => {
            if rdlen != 4 {
                d.pos = saved;
                return Ok(RData::Other {
                    type_num: rtype,
                    data: d.buf[start..start + rdlen].to_vec(),
                });
            }
            let b = d.read_bytes(4)?;
            RData::A(Ipv4Addr::new(b[0], b[1], b[2], b[3]))
        }
        28 => {
            if rdlen != 16 {
                d.pos = saved;
                return Ok(RData::Other {
                    type_num: rtype,
                    data: d.buf[start..start + rdlen].to_vec(),
                });
            }
            let b = d.read_bytes(16)?;
            let mut arr = [0u8; 16];
            arr.copy_from_slice(&b);
            RData::Aaaa(Ipv6Addr::from(arr))
        }
        2 => RData::Ns(d.read_name()?),
        5 => RData::Cname(d.read_name()?),
        12 => RData::Ptr(d.read_name()?),
        15 => {
            let preference = d.read_u16()?;
            let exchange = d.read_name()?;
            RData::Mx { preference, exchange }
        }
        6 => {
            let mname = d.read_name()?;
            let rname = d.read_name()?;
            let serial = d.read_u32()?;
            let refresh = d.read_u32()?;
            let retry = d.read_u32()?;
            let expire = d.read_u32()?;
            let minimum = d.read_u32()?;
            RData::Soa {
                mname,
                rname,
                serial,
                refresh,
                retry,
                expire,
                minimum,
            }
        }
        16 => {
            // TXT: concatenated character-strings.
            let mut msgs = Vec::new();
            while d.pos < start + rdlen {
                let l = d.read_u8()? as usize;
                let bytes = d.read_bytes(l)?;
                msgs.push(String::from_utf8_lossy(&bytes).into_owned());
            }
            RData::Txt(msgs)
        }
        33 => {
            let priority = d.read_u16()?;
            let weight = d.read_u16()?;
            let port = d.read_u16()?;
            let target = d.read_name()?;
            RData::Srv { priority, weight, port, target }
        }
        13 => {
            let l = d.read_u8()? as usize;
            let cpu = String::from_utf8_lossy(&d.read_bytes(l)?).into_owned();
            let l = d.read_u8()? as usize;
            let os = String::from_utf8_lossy(&d.read_bytes(l)?).into_owned();
            RData::Hinfo { cpu, os }
        }
        44 => {
            let algorithm = d.read_u8()?;
            let fp_type = d.read_u8()?;
            let fingerprint = d.read_bytes(rdlen - 2)?;
            RData::Sshfp {
                algorithm,
                fp_type,
                fingerprint,
            }
        }
        52 => {
            let usage = d.read_u8()?;
            let selector = d.read_u8()?;
            let matching_type = d.read_u8()?;
            let data = d.read_bytes(rdlen - 3)?;
            RData::Tlsa {
                usage,
                selector,
                matching_type,
                data,
            }
        }
        257 => {
            let flags = d.read_u8()?;
            let critical = (flags & 0x80) != 0;
            let tag_len = d.read_u8()? as usize;
            let tag = String::from_utf8_lossy(&d.read_bytes(tag_len)?).into_owned();
            let val = d.read_bytes(rdlen - 2 - tag_len)?;
            let value = String::from_utf8_lossy(&val).into_owned();
            RData::Caa { critical, tag, value }
        }
        35 => {
            let order = d.read_u16()?;
            let preference = d.read_u16()?;
            let l = d.read_u8()? as usize;
            let flags = String::from_utf8_lossy(&d.read_bytes(l)?).into_owned();
            let l = d.read_u8()? as usize;
            let service = String::from_utf8_lossy(&d.read_bytes(l)?).into_owned();
            let l = d.read_u8()? as usize;
            let regexp = String::from_utf8_lossy(&d.read_bytes(l)?).into_owned();
            let replacement = d.read_name()?;
            RData::Naptr {
                order,
                preference,
                flags,
                service,
                regexp,
                replacement,
            }
        }
        29 => {
            let version = d.read_u8()?;
            let size = d.read_u8()?;
            let horiz_pre = d.read_u8()?;
            let vert_pre = d.read_u8()?;
            let latitude = d.read_u32()?;
            let longitude = d.read_u32()?;
            let altitude = d.read_u32()?;
            RData::Loc {
                version,
                size,
                horiz_pre,
                vert_pre,
                latitude,
                longitude,
                altitude,
            }
        }
        41 => {
            let data = d.read_bytes(rdlen)?;
            RData::Opt {
                udp_payload_size: 0,
                ext_rcode: 0,
                edns_version: 0,
                flags: 0,
                data,
            }
        }
        _ => {
            let data = d.read_bytes(rdlen)?;
            RData::Other { type_num: rtype, data }
        }
    };
    Ok(rd)
}
RUST

