// Format durations.

pub fn format_ttl(secs: u32, always_seconds: bool) -> String {
    if always_seconds {
        return format!("{}", secs);
    }
    // Decompose into d, h, m, s.
    let days = secs / 86400;
    let hours = (secs % 86400) / 3600;
    let minutes = (secs % 3600) / 60;
    let seconds = secs % 60;

    // Style seen in the original:
    //   "5m00s", "2m20s", "10h16m00s", "1d0h00m00s", "7d0h00m00s"
    //   "0s", "13m42s", "3h00m00s", "2h46m40s", "29m59s", "30m00s"
    if days > 0 {
        format!("{}d{}h{:02}m{:02}s", days, hours, minutes, seconds)
    } else if hours > 0 {
        format!("{}h{:02}m{:02}s", hours, minutes, seconds)
    } else if minutes > 0 {
        format!("{}m{:02}s", minutes, seconds)
    } else {
        format!("{}s", seconds)
    }
}
