// Discover the system's default nameservers (from /etc/resolv.conf).

use std::fs;
use std::io::{self, BufRead};

pub fn system_nameservers() -> Result<Vec<String>, String> {
    let file = fs::File::open("/etc/resolv.conf")
        .map_err(|e| format!("failed to open /etc/resolv.conf: {}", e))?;
    let reader = io::BufReader::new(file);
    let mut out = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|e| format!("failed to read /etc/resolv.conf: {}", e))?;
        let line = line.split('#').next().unwrap_or("").trim().to_string();
        if let Some(rest) = line.strip_prefix("nameserver") {
            let ns = rest.trim().to_string();
            if !ns.is_empty() {
                out.push(ns);
            }
        }
    }
    Ok(out)
}
