// Send DNS queries over UDP or TCP.

use std::io::{Read, Write};
use std::net::{IpAddr, SocketAddr, TcpStream, ToSocketAddrs, UdpSocket};
use std::time::Duration;

pub enum TransportError {
    Network(String),
    Truncated(Vec<u8>),
}

impl TransportError {
    pub fn describe(&self) -> String {
        match self {
            TransportError::Network(m) => m.clone(),
            TransportError::Truncated(_) => "truncated".into(),
        }
    }
}

fn parse_nameserver(ns: &str, default_port: u16) -> Result<Vec<SocketAddr>, TransportError> {
    // Accept "1.2.3.4", "1.2.3.4:53", "[::1]:53", "name:port", etc.
    // First, try as a SocketAddr.
    if let Ok(a) = ns.parse::<SocketAddr>() {
        return Ok(vec![a]);
    }
    // Accept bracketed IPv6 without port.
    if ns.starts_with('[') && ns.ends_with(']') {
        let inner = &ns[1..ns.len() - 1];
        if let Ok(ip) = inner.parse::<IpAddr>() {
            return Ok(vec![SocketAddr::new(ip, default_port)]);
        }
    }
    // Try as bare IP address.
    if let Ok(ip) = ns.parse::<IpAddr>() {
        return Ok(vec![SocketAddr::new(ip, default_port)]);
    }
    // Fall back to a name:port lookup via OS resolver.
    let addr = if ns.contains(':') {
        ns.to_string()
    } else {
        format!("{}:{}", ns, default_port)
    };
    match addr.to_socket_addrs() {
        Ok(it) => Ok(it.collect()),
        Err(e) => Err(TransportError::Network(e.to_string())),
    }
}

pub fn send_udp(nameserver: &str, packet: &[u8]) -> Result<Vec<u8>, TransportError> {
    let addrs = parse_nameserver(nameserver, 53)?;
    let first = match addrs.into_iter().next() {
        Some(a) => a,
        None => return Err(TransportError::Network("no address for nameserver".into())),
    };
    let bind = if first.is_ipv6() { "[::]:0" } else { "0.0.0.0:0" };
    let sock = UdpSocket::bind(bind)
        .map_err(|e| TransportError::Network(e.to_string()))?;
    sock.set_read_timeout(Some(Duration::from_secs(10))).ok();
    sock.send_to(packet, first)
        .map_err(|e| TransportError::Network(e.to_string()))?;
    let mut buf = vec![0u8; 65535];
    let (n, _) = sock
        .recv_from(&mut buf)
        .map_err(|e| TransportError::Network(e.to_string()))?;
    buf.truncate(n);
    Ok(buf)
}

pub fn send_tcp(nameserver: &str, packet: &[u8]) -> Result<Vec<u8>, TransportError> {
    let addrs = parse_nameserver(nameserver, 53)?;
    let mut last_err: Option<TransportError> = None;
    for addr in addrs {
        match TcpStream::connect_timeout(&addr, Duration::from_secs(10)) {
            Ok(mut s) => {
                s.set_read_timeout(Some(Duration::from_secs(10))).ok();
                let len = packet.len() as u16;
                s.write_all(&len.to_be_bytes())
                    .map_err(|e| TransportError::Network(e.to_string()))?;
                s.write_all(packet)
                    .map_err(|e| TransportError::Network(e.to_string()))?;
                let mut lenbuf = [0u8; 2];
                s.read_exact(&mut lenbuf)
                    .map_err(|e| TransportError::Network(e.to_string()))?;
                let want = u16::from_be_bytes(lenbuf) as usize;
                let mut data = vec![0u8; want];
                s.read_exact(&mut data)
                    .map_err(|e| TransportError::Network(e.to_string()))?;
                return Ok(data);
            }
            Err(e) => last_err = Some(TransportError::Network(e.to_string())),
        }
    }
    Err(last_err.unwrap_or_else(|| TransportError::Network("no address for nameserver".into())))
}
