// Serialize DNS responses to JSON in the shape expected by dog.

use std::fmt::Write;
use std::time::Duration;

use crate::dns::{RData, Record, Response};
use crate::types;

pub fn format_responses(responses: &[Response], duration: Option<Duration>) -> String {
    let mut out = String::new();
    out.push('{');
    out.push_str("\"responses\":[");
    for (i, r) in responses.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        format_response(r, &mut out);
    }
    out.push(']');
    if let Some(d) = duration {
        let secs = d.as_secs();
        let millis = d.subsec_millis() as u64;
        write!(out, ",\"duration\":{{\"secs\":{},\"millis\":{}}}", secs, millis).ok();
    }
    out.push('}');
    out
}

fn format_response(r: &Response, out: &mut String) {
    out.push('{');
    out.push_str("\"queries\":[");
    for (i, q) in r.queries.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push('{');
        write!(out, "\"name\":{},", json_string(&q.name)).ok();
        write!(
            out,
            "\"class\":{},",
            json_string(&types::class_display(q.qclass))
        )
        .ok();
        write!(
            out,
            "\"type\":{}",
            json_string(types::type_name(q.qtype).unwrap_or("Other"))
        )
        .ok();
        out.push('}');
    }
    out.push(']');
    out.push_str(",\"answers\":[");
    for (i, rec) in r.answers.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        format_record(rec, out);
    }
    out.push(']');
    out.push_str(",\"authorities\":[");
    for (i, rec) in r.authorities.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        format_record(rec, out);
    }
    out.push(']');
    out.push_str(",\"additionals\":[");
    for (i, rec) in r.additionals.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        format_record(rec, out);
    }
    out.push(']');
    out.push('}');
}

fn format_record(rec: &Record, out: &mut String) {
    out.push('{');
    if rec.rtype == 41 {
        write!(out, "\"name\":{},", json_string(&rec.name)).ok();
        out.push_str("\"type\":\"OPT\",\"data\":{");
        if let RData::Opt { edns_version, data, .. } = &rec.data {
            write!(out, "\"version\":{},\"data\":[", edns_version).ok();
            for (i, b) in data.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write!(out, "{}", b).ok();
            }
            out.push(']');
        }
        out.push('}');
        out.push('}');
        return;
    }
    write!(out, "\"name\":{},", json_string(&rec.name)).ok();
    write!(
        out,
        "\"class\":{},",
        json_string(&types::class_display(rec.rclass))
    )
    .ok();
    write!(out, "\"ttl\":{},", rec.ttl).ok();
    let tn = rec
        .data
        .type_name()
        .unwrap_or_else(|| types::type_name(rec.rtype).unwrap_or("Other"));
    write!(out, "\"type\":{},", json_string(tn)).ok();
    out.push_str("\"data\":");
    format_rdata(&rec.data, rec.rtype, out);
    out.push('}');
}

