                    out.push(',');
                }
                write!(out, "{}", json_string(m)).ok();
            }
            out.push(']');
            out.push('}');
        }
        RData::Caa { critical, tag, value } => {
            out.push('{');
            write!(
                out,
                "\"critical\":{},\"tag\":{},\"value\":{}",
                critical,
                json_string(tag),
                json_string(value)
            )
            .ok();
            out.push('}');
        }
        RData::Srv { priority, weight, port, target } => {
            out.push('{');
            write!(
                out,
                "\"priority\":{},\"weight\":{},\"port\":{},\"target\":{}",
                priority,
                weight,
                port,
                json_string(target)
            )
            .ok();
            out.push('}');
        }
        RData::Hinfo { cpu, os } => {
            out.push('{');
            write!(
                out,
                "\"cpu\":{},\"os\":{}",
                json_string(cpu),
                json_string(os)
            )
            .ok();
            out.push('}');
        }
        RData::Naptr { order, preference, flags, service, regexp, replacement } => {
            out.push('{');
            write!(
                out,
                "\"order\":{},\"preference\":{},\"flags\":{},\"service\":{},\"regexp\":{},\"replacement\":{}",
                order,
                preference,
                json_string(flags),
                json_string(service),
                json_string(regexp),
                json_string(replacement)
            )
            .ok();
            out.push('}');
        }
        RData::Loc { version, .. } => {
            out.push('{');
            write!(out, "\"version\":{}", version).ok();
            out.push('}');
        }
        RData::Sshfp { algorithm, fp_type, fingerprint } => {
            out.push('{');
            write!(
                out,
                "\"algorithm\":{},\"fptype\":{},\"fingerprint\":\"{}\"",
                algorithm,
                fp_type,
                hex(fingerprint)
            )
            .ok();
            out.push('}');
        }
        RData::Tlsa { usage, selector, matching_type, data } => {
            out.push('{');
            write!(
                out,
                "\"usage\":{},\"selector\":{},\"matching_type\":{},\"data\":\"{}\"",
                usage,
                selector,
                matching_type,
                hex(data)
            )
            .ok();
            out.push('}');
        }
        RData::Opt { edns_version, data, .. } => {
            out.push('{');
            write!(out, "\"version\":{},\"data\":[", edns_version).ok();
            for (i, b) in data.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write!(out, "{}", b).ok();
            }
            out.push(']');
            out.push('}');
        }
        RData::Other { data, .. } => {
            out.push('{');
            let _ = rtype;
            out.push_str("\"data\":[");
            for (i, b) in data.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write!(out, "{}", b).ok();
            }
            out.push(']');
            out.push('}');
        }
    }
}

pub fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0C}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                write!(out, "\\u{:04x}", c as u32).ok();
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        write!(s, "{:02x}", b).ok();
    }
    s
}
