// Orchestrate queries, then pretty-print a table or short/JSON output.

use std::fmt::Write;
use std::process::ExitCode;
use std::time::Instant;

use crate::args::{EdnsSetting, Options, OutputFormat, Protocol, UseColour};
use crate::dns::{RData, Record, Response};
use crate::duration;
use crate::json as jsonfmt;
use crate::resolver;
use crate::transport;
use crate::types;
use crate::wire;

const C_TYPE: &str = "\x1b[1;32m";
const C_NAME: &str = "\x1b[1;34m";
const C_RESET: &str = "\x1b[0m";

pub fn run(opts: Options, stdout_tty: bool) -> ExitCode {
    // Build the list of queries to execute.
    let mut queries = Vec::new();
    for q in &opts.queries {
        for t in &opts.types {
            for c in &opts.classes {
                queries.push(crate::dns::Query {
                    name: normalise_name(q),
                    qtype: *t,
                    qclass: *c,
                });
            }
        }
    }

    // Resolve nameservers.
    let nameservers = if !opts.nameservers.is_empty() {
        opts.nameservers.clone()
    } else {
        match resolver::system_nameservers() {
            Ok(v) if !v.is_empty() => v,
            Ok(_) => {
                eprintln!("Error [resolver]: no nameservers configured");
                return ExitCode::from(4);
            }
            Err(e) => {
                eprintln!("Error [resolver]: {}", e);
                return ExitCode::from(4);
            }
        }
    };

    // Execute queries; each combination of query * protocol results in one
    // response. We store them in-order.
    let mut responses = Vec::new();
    let start = Instant::now();
    for protocol in &opts.protocols {
        for q in &queries {
            match execute_query(q, &nameservers, *protocol, &opts) {
                Ok(resp) => responses.push(resp),
                Err(e) => {
                    eprintln!("Error [network]: {}", e);
                    return ExitCode::from(1);
                }
            }
        }
    }
    let elapsed = start.elapsed();

    let colour = opts.colour.active(stdout_tty);
    let duration = if opts.time { Some(elapsed) } else { None };
    match opts.format {
        OutputFormat::Json => {
            println!("{}", jsonfmt::format_responses(&responses, duration));
        }
        OutputFormat::Short => {
            let mut shown = false;
            for r in &responses {
                for rec in &r.answers {
                    if let Some(s) = short_line(&rec.data) {
                        println!("{}", s);
                        shown = true;
                    }
                }
            }
            if !shown {
                eprintln!("No results");
                return ExitCode::from(2);
            }
        }
        OutputFormat::Text => {
            print_table(&responses, colour);
            if let Some(d) = duration {
                println!("Ran in {}ms", d.as_millis());
            }
        }
    }
    ExitCode::from(0)
}

fn execute_query(
    q: &crate::dns::Query,
    nameservers: &[String],
    protocol: Protocol,
    opts: &Options,
) -> Result<Response, String> {
    let txid = opts.txid.unwrap_or_else(|| random_txid());
    let queries = vec![q.clone()];
    let packet = wire::build_query(txid, &queries, opts.edns, &opts.tweaks);
    let server = nameservers.first().ok_or("no nameserver available")?;
    let data = match protocol {
        Protocol::Udp => {
            let bytes = transport::send_udp(server, &packet)
                .map_err(|e| e.describe())?;
            // If the response is truncated, retry over TCP (unless the user
            // explicitly wanted UDP only by omitting --tcp fallback).
            let r = wire::decode(&bytes).map_err(|e| e)?;
            if r.truncated() {
                let bytes = transport::send_tcp(server, &packet)
                    .map_err(|e| e.describe())?;
                return wire::decode(&bytes);
            }
            return Ok(r);
        }
        Protocol::Tcp => transport::send_tcp(server, &packet).map_err(|e| e.describe())?,
        Protocol::Tls => return Err("DoT is not supported in this build".into()),
        Protocol::Https => return Err("DoH is not supported in this build".into()),
    };
    wire::decode(&data)
}

fn random_txid() -> u16 {
    use std::time::SystemTime;
    let d = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();
    ((d.as_nanos() as u64) & 0xFFFF) as u16
}

fn normalise_name(n: &str) -> String {
    let n = n.trim().to_string();
    n
}

fn short_line(data: &RData) -> Option<String> {
    match data {
        RData::A(a) => Some(a.to_string()),
        RData::Aaaa(a) => Some(a.to_string()),
        RData::Cname(n) => Some(format!("\"{}\"", n)),
        RData::Ns(n) => Some(format!("\"{}\"", n)),
