// Orchestrate queries, then pretty-print a table or short/JSON output.

use std::fmt::Write;
use std::process::ExitCode;
use std::time::{Duration, Instant};

use crate::args::{EdnsSetting, Options, OutputFormat, Protocol};
use crate::dns::{RData, Record, Response};
use crate::duration;
use crate::json as jsonfmt;
use crate::resolver;
use crate::transport;
use crate::wire;

const C_TYPE: &str = "\x1b[1;32m";
const C_NAME: &str = "\x1b[1;34m";
const C_RESET: &str = "\x1b[0m";

pub fn run(opts: Options, stdout_tty: bool) -> ExitCode {
    // Build the queries to run.
    let mut queries = Vec::new();
    for q in &opts.queries {
        for t in &opts.types {
            for c in &opts.classes {
                queries.push(crate::dns::Query {
                    name: q.clone(),
                    qtype: *t,
                    qclass: *c,
                });
            }
        }
    }

    // Resolve nameservers.
    let nameservers = if !opts.nameservers.is_empty() {
        opts.nameservers.clone()
    } else {
        match resolver::system_nameservers() {
            Ok(v) if !v.is_empty() => v,
            Ok(_) => {
                eprintln!("Error [resolver]: no nameservers configured");
                return ExitCode::from(4);
            }
            Err(e) => {
                eprintln!("Error [resolver]: {}", e);
                return ExitCode::from(4);
            }
        }
    };

    let mut responses = Vec::new();
    let start = Instant::now();
    for protocol in &opts.protocols {
        for q in &queries {
            match execute_query(q, &nameservers, *protocol, &opts) {
                Ok(resp) => responses.push(resp),
                Err(e) => {
                    eprintln!("Error [network]: {}", e);
                    return ExitCode::from(1);
                }
            }
        }
    }
    let elapsed = start.elapsed();

    let colour = opts.colour.active(stdout_tty);
    let duration = if opts.time { Some(elapsed) } else { None };
    match opts.format {
        OutputFormat::Json => {
            println!("{}", jsonfmt::format_responses(&responses, duration));
        }
        OutputFormat::Short => {
            let mut shown = false;
            for r in &responses {
                for rec in &r.answers {
                    if let Some(s) = short_line(&rec.data, opts.seconds) {
                        println!("{}", s);
                        shown = true;
                    }
                }
            }
            if !shown {
                eprintln!("No results");
                return ExitCode::from(2);
            }
        }
        OutputFormat::Text => {
            print_table(&responses, colour, &opts);
            if let Some(d) = duration {
                print_ran_in(d);
            }
        }
    }
    ExitCode::from(0)
}

fn print_ran_in(d: Duration) {
    println!("Ran in {}ms", d.as_millis());
}

fn execute_query(
    q: &crate::dns::Query,
    nameservers: &[String],
    protocol: Protocol,
    opts: &Options,
) -> Result<Response, String> {
    let txid = opts.txid.unwrap_or_else(random_txid);
    let queries = vec![q.clone()];
    let packet = wire::build_query(txid, &queries, opts.edns, &opts.tweaks);
    let server = nameservers.first().ok_or("no nameserver available")?;
    match protocol {
        Protocol::Udp => {
            let bytes = transport::send_udp(server, &packet).map_err(|e| e.describe())?;
            let r = wire::decode(&bytes)?;
            if r.truncated() {
                let bytes = transport::send_tcp(server, &packet).map_err(|e| e.describe())?;
                return wire::decode(&bytes);
            }
            Ok(r)
        }
        Protocol::Tcp => {
            let bytes = transport::send_tcp(server, &packet).map_err(|e| e.describe())?;
            wire::decode(&bytes)
        }
        Protocol::Tls => Err("DoT is not supported in this build".into()),
        Protocol::Https => Err("DoH is not supported in this build".into()),
    }
}

fn random_txid() -> u16 {
    use std::time::SystemTime;
    let d = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .unwrap_or_default();
    (d.as_nanos() as u64 & 0xFFFF) as u16
}

