cd /workspace && for t in A AAAA CNAME MX NS SOA PTR TXT SRV CAA HINFO SSHFP TLSA LOC NAPTR OPT NSEC RP KEY AFSDB; do
  # Get a response with that record type in any section (answer/auth/additional)
  case $t in
    A) domain="example.com";;
    AAAA) domain="example.com";;
    MX) domain="google.com";;
    NS) domain="google.com";;
    SOA) domain="google.com";;
    TXT) domain="google.com";;
    CNAME) domain="www.google.com -t CNAME";;
    PTR) domain="1.1.1.1.in-addr.arpa -t PTR";;
    SRV) domain="_xmpp-server._tcp.xmpp.org -t SRV";;
    CAA) domain="google.com -t CAA";;
    HINFO) domain="hcs_wrdc_net.quest.com -t HINFO";;
    SSHFP) domain="nsa.gov -t SSHFP";;
    TLSA) domain="_443._tcp.good.dane.huque.com -t TLSA";;
    LOC) domain="kiit.edu -t LOC";;
    NAPTR) domain="sip.edvina.net -t NAPTR";;
    OPT) continue;;
    NSEC) domain="dnssec-name-and-shame.com -t NSEC";;
    RP) domain="example.com -t RP";;
    KEY) domain="example.com -t KEY";;
    AFSDB) domain="example.com -t AFSDB";;
  esac
  out=$(./executable --color=always $domain -t $t 2>&1 | grep -oP "^[^ ]*\x1b\[[0-9;]+m$t" | head -1)
  color=$(echo "$out" | grep -oP '\x1b\[[0-9;]+m' | head -1)
  printf "%-8s: " "$t"
  echo -n "$color" | od -c | head -1
done 2>&1 | head -30

