// Command-line argument parsing.

use crate::types;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UseColour {
    Always,
    Automatic,
    Never,
}

impl UseColour {
    pub fn active(self, stdout_tty: bool) -> bool {
        match self {
            UseColour::Always => true,
            UseColour::Never => false,
            UseColour::Automatic => stdout_tty,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum EdnsSetting {
    Disable,
    Hide,
    Show,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Protocol {
    Udp,
    Tcp,
    Tls,
    Https,
}

#[derive(Clone, Debug)]
pub struct Tweaks {
    pub aa: bool,
    pub ad: bool,
    pub cd: bool,
    pub bufsize: u16,
}
impl Default for Tweaks {
    fn default() -> Self {
        Self {
            aa: false,
            ad: false,
            cd: false,
            bufsize: 512,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum OutputFormat {
    Text,
    Short,
    Json,
}

#[derive(Clone, Debug)]
pub struct Options {
    pub queries: Vec<String>,
    pub types: Vec<u16>,
    pub classes: Vec<u16>,
    pub nameservers: Vec<String>,
    pub protocols: Vec<Protocol>,
    pub edns: EdnsSetting,
    pub txid: Option<u16>,
    pub tweaks: Tweaks,
    pub colour: UseColour,
    pub format: OutputFormat,
    pub time: bool,
    pub seconds: bool,
}

pub enum ParseResult {
    Help { exit_code: u8 },
    Version(UseColour),
    Error(String),
    Run(Options),
}

/// Parse the command-line arguments into an Options structure, or return
/// a special result for help/version/errors.
pub fn parse(argv: &[String], _stdout_tty: bool) -> ParseResult {
    let mut opts = Options {
        queries: Vec::new(),
        types: Vec::new(),
        classes: Vec::new(),
        nameservers: Vec::new(),
        protocols: Vec::new(),
        edns: EdnsSetting::Hide,
        txid: None,
        tweaks: Tweaks::default(),
        colour: UseColour::Automatic,
        format: OutputFormat::Text,
        time: false,
        seconds: false,
    };
    // Track which unique-only options have been seen.
    let mut seen: std::collections::HashSet<&'static str> = std::collections::HashSet::new();
    let mut want_help = false;
    let mut want_version = false;
    let mut positional_only = false;

    macro_rules! set_once {
        ($name:expr) => {{
            if !seen.insert($name) {
                return ParseResult::Error(format!("Option '{}' given more than once", $name));
            }
        }};
    }

    let mut i = 0;

    while i < argv.len() {
        let arg = &argv[i];
        if positional_only {
            if let Err(e) = handle_positional_strict(arg, &mut opts) {
                return ParseResult::Error(e);
            }
            i += 1;
            continue;
        }
        if arg == "--" {
            positional_only = true;
            i += 1;
            continue;
        }
        if arg == "--help" {
            set_once!("help");
            want_help = true;
            i += 1;
            continue;
        }
        if arg == "-?" {
            set_once!("help");
            want_help = true;
            i += 1;
            continue;
        }
        if arg == "--version" {
            set_once!("version");
            want_version = true;
            i += 1;
            continue;
        }
        if arg == "-v" {
            set_once!("version");
            want_version = true;
            i += 1;
            continue;
        }
        if let Some(rest) = arg.strip_prefix("--") {
            let (name, value_in_arg) = match rest.split_once('=') {
                Some((n, v)) => (n.to_string(), Some(v.to_string())),
                None => (rest.to_string(), None),
            };
            let name_str: &str = &name;
            let take_value =
                |idx: &mut usize, value_in_arg: Option<String>| -> Result<String, String> {
                    if let Some(v) = value_in_arg {
                        Ok(v)
                    } else {
                        *idx += 1;
                        if *idx >= argv.len() {
                            return Err(format!("Argument to option '{}' missing", name_str));
                        }
                        Ok(argv[*idx].clone())
                    }
                };
            match name.as_str() {
                "query" => match take_value(&mut i, value_in_arg) {
                    Ok(v) => opts.queries.push(v),
                    Err(e) => return ParseResult::Error(e),
                },
                "type" => match take_value(&mut i, value_in_arg) {
                    Ok(v) => match types::parse_type(&v) {
                        Some(t) => {
                            if t == 41 {
                                return ParseResult::Error(
                                    "OPT request is sent by default (see -Z flag)".into(),
                                );
                            }
                            opts.types.push(t);
                        }
                        None => return ParseResult::Error(format!("Invalid query type {:?}", v)),
                    },
                    Err(e) => return ParseResult::Error(e),
                },
                "nameserver" => match take_value(&mut i, value_in_arg) {
                    Ok(v) => opts.nameservers.push(v),
                    Err(e) => return ParseResult::Error(e),
                },
                "class" => match take_value(&mut i, value_in_arg) {
                    Ok(v) => match types::parse_class(&v) {
                        Some(c) => opts.classes.push(c),
                        None => return ParseResult::Error(format!("Invalid query class {:?}", v)),
                    },
                    Err(e) => return ParseResult::Error(e),
                },
                "edns" => {
                    if seen.contains("edns") {
                        return ParseResult::Error("Option 'edns' given more than once".into());
                    }
                    seen.insert("edns");
                    match take_value(&mut i, value_in_arg) {
                        Ok(v) => match v.as_str() {
                            "disable" => opts.edns = EdnsSetting::Disable,
                            "hide" => opts.edns = EdnsSetting::Hide,
                            "show" => opts.edns = EdnsSetting::Show,
                            _ => {
                                return ParseResult::Error(format!("Invalid EDNS setting {:?}", v))
                            }
                        },
                        Err(e) => return ParseResult::Error(e),
                    }
                }
                "txid" => {
                    if seen.contains("txid") {
                        return ParseResult::Error("Option 'txid' given more than once".into());
                    }
                    seen.insert("txid");
                    match take_value(&mut i, value_in_arg) {
                        Ok(v) => match parse_txid(&v) {
                            Some(n) => opts.txid = Some(n),
                            None => {
                                return ParseResult::Error(format!(
                                    "Invalid transaction ID {:?}",
                                    v
                                ))
                            }
                        },
                        Err(e) => return ParseResult::Error(e),
                    }
                }
                "color" => {
                    if seen.contains("color") {
                        return ParseResult::Error("Option 'color' given more than once".into());
                    }
                    seen.insert("color");
                    match take_value(&mut i, value_in_arg) {
                        Ok(v) => set_colour(&mut opts, &v, "color"),
                        Err(e) => return ParseResult::Error(e),
                    }?;
                }
                "colour" => {
                    if seen.contains("colour") {
                        return ParseResult::Error("Option 'colour' given more than once".into());
                    }
                    seen.insert("colour");
                    match take_value(&mut i, value_in_arg) {
                        Ok(v) => set_colour(&mut opts, &v, "colour"),
                        Err(e) => return ParseResult::Error(e),
                    }?;
                }
                "udp" => {
                    set_once!("udp");
                    opts.protocols.push(Protocol::Udp);
                }
                "tcp" => {
                    set_once!("tcp");
                    opts.protocols.push(Protocol::Tcp);
                }
                "tls" => {
                    set_once!("tls");
                    opts.protocols.push(Protocol::Tls);
                }
                "https" => {
                    set_once!("https");
                    opts.protocols.push(Protocol::Https);
                }
                "short" => {
                    set_once!("short");
                    opts.format = OutputFormat::Short;
                }
                "json" => {
                    set_once!("json");
                    if opts.format != OutputFormat::Short {
                        opts.format = OutputFormat::Json;
                    }
                }
                "time" => {
                    set_once!("time");
                    opts.time = true;
                }
                "seconds" => {
                    set_once!("seconds");
                    opts.seconds = true;
                }
                _ => return ParseResult::Error(format!("Unrecognized option: '{}'", name)),
            }
            i += 1;
            continue;
        }
        if arg.starts_with('-') && arg.len() >= 2 {
            let body = &arg[1..];
            let bytes = body.as_bytes();
            let mut j = 0;
            while j < bytes.len() {
                let c = bytes[j] as char;
                match c {
                    'U' => {
                        set_once!("udp");
                        opts.protocols.push(Protocol::Udp);
                    }
                    'T' => {
                        set_once!("tcp");
                        opts.protocols.push(Protocol::Tcp);
                    }
                    'S' => {
                        set_once!("tls");
                        opts.protocols.push(Protocol::Tls);
                    }
                    'H' => {
                        set_once!("https");
                        opts.protocols.push(Protocol::Https);
                    }
                    '1' => {
                        set_once!("short");
                        opts.format = OutputFormat::Short;
                    }
                    'J' => {
                        set_once!("json");
                        if opts.format != OutputFormat::Short {
                            opts.format = OutputFormat::Json;
                        }
                    }
                    'v' => {
                        set_once!("version");
                        want_version = true;
                    }
                    '?' => {
                        set_once!("help");
                        want_help = true;
                    }
                    'q' | 't' | 'n' | 'Z' => {
                        let mut rest = String::from_utf8_lossy(&bytes[j + 1..]).into_owned();
                        let value = if !rest.is_empty() {
                            if rest.starts_with('=') {
                                rest.remove(0);
                            }
                            rest
                        } else {
                            i += 1;
                            if i >= argv.len() {
                                return ParseResult::Error(format!(
                                    "Argument to option '{}' missing",
                                    c
                                ));
                            }
                            argv[i].clone()
                        };
                        match c {
                            'q' => opts.queries.push(value),
                            't' => match types::parse_type(&value) {
                                Some(t) => {
                                    if t == 41 {
                                        return ParseResult::Error(
                                            "OPT request is sent by default (see -Z flag)".into(),
                                        );
                                    }
                                    opts.types.push(t)
                                }
                                None => {
                                    return ParseResult::Error(format!(
                                        "Invalid query type {:?}",
                                        value
                                    ))
                                }
                            },
                            'n' => opts.nameservers.push(value),
                            'Z' => {
                                if let Err(e) = parse_tweak(&value, &mut opts.tweaks) {
                                    return ParseResult::Error(e);
                                }
                            }
                            _ => unreachable!(),
                        }
                        j = bytes.len();
                        continue;
                    }
                    _ => return ParseResult::Error(format!("Unrecognized option: '{}'", c)),
                }
                j += 1;
            }
            i += 1;
            continue;
        }
        if let Err(e) = handle_positional(arg, &mut opts) {
            return ParseResult::Error(e);
        }
        i += 1;
    }

    if want_version {
        return ParseResult::Version(opts.colour);
    }
    if want_help {
        return ParseResult::Help { exit_code: 0 };
    }
    if opts.queries.is_empty() {
        return ParseResult::Help { exit_code: 3 };
    }
    if opts.protocols.is_empty() {
        opts.protocols.push(Protocol::Udp);
    }
    if opts.types.is_empty() {
        opts.types.push(1);
    }
    if opts.classes.is_empty() {
        opts.classes.push(1);
    }
    if opts.protocols.iter().any(|p| *p == Protocol::Https) && opts.nameservers.is_empty() {
        return ParseResult::Error(
            "You must pass a URL as a nameserver when using --https".into(),
        );
    }
    ParseResult::Run(opts)
}

fn set_colour(opts: &mut Options, v: &str, _name: &str) -> Result<(), ParseResult> {
    match v {
        "always" => opts.colour = UseColour::Always,
        "automatic" | "auto" => opts.colour = UseColour::Automatic,
        "never" => opts.colour = UseColour::Never,
        other => {
            return Err(ParseResult::Error(format!(
                "Invalid colour setting {:?}",
                other
            )))
        }
    }
    Ok(())
}

fn handle_positional(arg: &str, opts: &mut Options) -> Result<(), String> {
    if let Some(ns) = arg.strip_prefix('@') {
        opts.nameservers.push(ns.to_string());
        return Ok(());
    }
    if let Some(t) = types::parse_type(arg) {
        if t == 41 {
            return Err("OPT request is sent by default (see -Z flag)".into());
        }
        opts.types.push(t);
        return Ok(());
    }
    if let Some(c) = types::parse_class(arg) {
        opts.classes.push(c);
        return Ok(());
    }
    if arg.starts_with('-') {
        return Err(format!("Invalid domain {:?}", arg));
    }
    opts.queries.push(arg.to_string());
    Ok(())
}

fn handle_positional_strict(arg: &str, opts: &mut Options) -> Result<(), String> {
    if arg.starts_with('-') {
        return Err(format!("Invalid domain {:?}", arg));
    }
    opts.queries.push(arg.to_string());
    Ok(())
}

fn parse_txid(s: &str) -> Option<u16> {
    if let Some(rest) = s.strip_prefix("0x").or_else(|| s.strip_prefix("0X")) {
        u16::from_str_radix(rest, 16).ok()
    } else {
        s.parse::<u16>().ok()
    }
}

fn parse_tweak(s: &str, tweaks: &mut Tweaks) -> Result<(), String> {
    match s {
        "aa" => {
            tweaks.aa = true;
            Ok(())
        }
        "ad" => {
            tweaks.ad = true;
            Ok(())
        }
        "cd" => {
            tweaks.cd = true;
            Ok(())
        }
        other => {
            if let Some(rest) = other.strip_prefix("bufsize=") {
                match rest.parse::<u16>() {
                    Ok(n) => {
                        tweaks.bufsize = n;
                        Ok(())
                    }
                    Err(_) => Err(format!("Invalid protocol tweak {:?}", other)),
                }
            } else {
                Err(format!("Invalid protocol tweak {:?}", other))
            }
        }
    }
}

pub const HELP: &str = "\
dog \u{25CF} command-line DNS client

Usage:
  dog [OPTIONS] [--] <arguments>

Examples:
  dog example.net                          Query a domain using default settings
  dog example.net MX                       ...looking up MX records instead
  dog example.net MX @1.1.1.1              ...using a specific nameserver instead
  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP
  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments

Query options:
  <arguments>              Human-readable host names, nameservers, types, or classes
  -q, --query=HOST         Host name or domain name to query
  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)
  -n, --nameserver=ADDR    Address of the nameserver to send packets to
  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)

Sending options:
  --edns=SETTING           Whether to OPT in to EDNS (disable, hide, show)
  --txid=NUMBER            Set the transaction ID to a specific value
  -Z=TWEAKS                Set uncommon protocol-level tweaks

Protocol options:
  -U, --udp                Use the DNS protocol over UDP
  -T, --tcp                Use the DNS protocol over TCP
  -S, --tls                Use the DNS-over-TLS protocol
  -H, --https              Use the DNS-over-HTTPS protocol

Output options:
  -1, --short              Short mode: display nothing but the first result
  -J, --json               Display the output as JSON
  --color, --colour=WHEN   When to colourise the output (always, automatic, never)
  --seconds                Do not format durations, display them as seconds
  --time                   Print how long the response took to arrive

Meta options:
  -?, --help               Print list of command-line options
  -v, --version            Print version information
";

pub fn help_text() -> &'static str {
    HELP
}

pub fn version_text(colour: UseColour) -> String {
    use std::io::IsTerminal;
    let tty = std::io::stdout().is_terminal();
    let on = colour.active(tty);
